/// Counts how often each word occurs in `text` (case-insensitive keys).
pub fn word_freq(text: Str) -> Map[Str, Int] {
  var counts: Map[Str, Int] = Map {}
  for w in text.split(" ") {
    if not w.is_empty() {
      let k = w.lower()
      let n = match counts.get(k) {
        Some(c) => c + 1,
        None => 1,
      }
      counts = counts.set(k, n)
    }
  }
  return counts
}
