/// The k most frequent words, most frequent first, ties in alphabetical order.
pub fn top_k(words: List[Str], k: Int) -> List[Str] {
  var counts: Map[Str, Int] = Map {}
  for w in words {
    let n = match counts.get(w) {
      Some(c) => c + 1,
      None => 1,
    }
    counts = counts.set(w, n)
  }
  var left: List[Str] = words.unique().sort()
  var out: List[Str] = []
  var taken = 0
  while taken < k and not left.is_empty() {
    var best_word = ""
    var best_count = 0
    for w in left {
      let c = counts.get(w).unwrap_or(0)
      if c > best_count {
        best_word = w
        best_count = c
      }
    }
    let chosen = best_word
    out = out.push(chosen)
    left = left.filter(fn(w) => w != chosen)
    taken = taken + 1
  }
  return out
}
