/// The Roman numeral of `n` (1..3999), or an error outside that range.
pub fn to_roman(n: Int) -> Result[Str, Str] {
  if n < 1 or n > 3999 {
    return Err("out of range")
  }
  let vals = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
  let syms = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]
  var rest = n
  var out = ""
  for i in range(0, 13) {
    let v = vals.get_or(i, 0)
    let s = syms.get_or(i, "")
    while rest >= v {
      out = out + s
      rest = rest - v
    }
  }
  return Ok(out)
}
