/// Shifts each ASCII letter by `shift` places, wrapping and keeping case.
pub fn caesar(text: Str, shift: Int) -> Str {
  let k = ((shift % 26) + 26) % 26
  var out = ""
  for c in text.chars() {
    let code = c.codes().get_or(0, 0)
    if code >= 65 and code <= 90 {
      let n = (code - 65 + k) % 26 + 65
      out = out + match n.to_char() {
        Some(x) => x,
        None => c,
      }
    } else if code >= 97 and code <= 122 {
      let n = (code - 97 + k) % 26 + 97
      out = out + match n.to_char() {
        Some(x) => x,
        None => c,
      }
    } else {
      out = out + c
    }
  }
  return out
}
