/// The n-th Fibonacci number modulo m (fib(0) = 0, fib(1) = 1), in linear time.
pub fn fib_mod(n: Int, m: Int) -> Int {
  if m == 0 {
    return 0
  }
  var a = 0
  var b = 1 % m
  var i = 0
  while i < n {
    let t = (a + b) % m
    a = b
    b = t
    i = i + 1
  }
  return a
}
