export function parse_csv_line(line: string): string[] {
  const fields: string[] = [];
  let cur = "";
  let i = 0;
  const n = line.length;
  while (true) {
    if (i < n && line[i] === '"' && cur === "") {
      // quoted field
      i++;
      let closed = false;
      while (i < n) {
        if (line[i] === '"') {
          if (i + 1 < n && line[i + 1] === '"') {
            cur += '"';
            i += 2;
          } else {
            closed = true;
            i++;
            break;
          }
        } else {
          cur += line[i];
          i++;
        }
      }
      if (!closed) throw new Error("unterminated quote");
      // after closing quote, consume until comma or end
      while (i < n && line[i] !== ",") {
        cur += line[i];
        i++;
      }
    } else {
      while (i < n && line[i] !== ",") {
        cur += line[i];
        i++;
      }
    }
    fields.push(cur);
    cur = "";
    if (i >= n) break;
    // line[i] is a comma
    i++;
    if (i >= n) {
      fields.push("");
      break;
    }
  }
  return fields;
}
